// Monta o pedido ao Gemini. Sem avaliacao nova: nenhum item sai e o fluxo para aqui.
const r = $input.first().json || {};
const itens = r.itens || [];
if (!itens.length) return [];
const temas = (r.temas || []).map(t => `#${t.id} | ${t.titulo} | melhoria: ${t.melhoria || '-'} | ${t.qtd} avaliacoes`).join('\n') || '(nenhum ainda)';
const lista = itens.map(a => `id ${a.id} | nota ${a.nota} | ocorrencia: ${a.categoria} - ${a.problema || ''} | solucao dada: ${a.solucao || '-'}` +
  ` | motivos: ${(a.motivos || []).join('; ') || '-'} | texto: ${a.observacao}`).join('\n');
const SYS = "Voce organiza as criticas dos motoristas de onibus sobre o atendimento de problemas no celular do onibus\n(celular com o app da viagem, leitor RFID que conta passageiros, carregador/cabo, suporte do celular, chip/internet).\nCada avaliacao traz a nota (1 a 5), os motivos marcados e o texto do motorista.\nPara cada avaliacao escolha UM tema que diga o mesmo problema de fundo:\n- Use um tema EXISTENTE (tema_id) sempre que ele servir, mesmo com palavras diferentes.\n  Ex.: \"podia ter trocado o suporte\", \"o suporte continuou quebrado\" e \"o suporte esta quase quebrando\" sao o MESMO tema.\n- So crie tema novo (novo_titulo + nova_melhoria) quando nenhum existente servir.\n  Avaliacoes deste lote que dizem a mesma coisa recebem EXATAMENTE o mesmo novo_titulo.\n- novo_titulo: o problema, especifico e curto (ate 60 caracteres). Ex.: \"Suporte do celular nao foi resolvido de vez\".\n  Nada generico como \"Problemas\" ou \"Insatisfacao\".\n- nova_melhoria: o que a equipe deve fazer, comecando com verbo (ate 120 caracteres).\n  Ex.: \"Verificar o suporte com mais frequencia durante a vistoria\".\n- sem_tema = true quando o texto nao traz critica nem sugestao (ex.: \"nada\", \"ok\", \"tudo certo\").\nResponda em portugues do Brasil.";
return [{ json: {
  ids: itens.map(a => a.id),
  pedido: {
    system_instruction: { parts: [{ text: SYS }] },
    contents: [{ role: 'user', parts: [{ text: `TEMAS QUE JA EXISTEM:\n${temas}\n\nAVALIACOES PARA AGRUPAR:\n${lista}` }] }],
    generationConfig: { temperature: 0.1, responseMimeType: 'application/json',
      responseSchema: { type: 'OBJECT', properties: { itens: { type: 'ARRAY', items: { type: 'OBJECT', properties: {
        id: { type: 'INTEGER' }, tema_id: { type: 'INTEGER', nullable: true }, novo_titulo: { type: 'STRING' },
        nova_melhoria: { type: 'STRING' }, sem_tema: { type: 'BOOLEAN' } }, required: ['id'] } } }, required: ['itens'] } },
  },
} }];

// Le a resposta do Gemini. Se falhar (cota, erro), nada e gravado e as avaliacoes voltam no proximo ciclo.
const ids = $('Montar pedido IA').first().json.ids;
const g = $input.first().json || {};
if (g.error) throw new Error('Gemini: ' + (g.error.message || JSON.stringify(g.error)));
const txt = (g.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
const r = JSON.parse(txt);
const itens = (r.itens || []).filter(i => ids.includes(i.id));
if (!itens.length) return [];
return [{ json: { p: { itens } } }];
